/* Logos de la empresa (R Motriz): fondo transparente. dark = para fondo oscuro (la app); light = para papel blanco (documentos). */
const R77_LOGO={"dark": "data:image/png;base64,", "light": "data:image/png;base64,"};

const r77LogoD=()=>{try{return r73Company().logoDark||R77_LOGO.dark}catch{return R77_LOGO.dark}};
const r77LogoL=()=>{try{return r73Company().logoLight||R77_LOGO.light}catch{return R77_LOGO.light}};
